let __v_322 = Value::from("One litre of emulsion covers about 10 to 12 square metres, and you need two coats, so count the wall area and double it: add the walls up as perimeter times ceiling height (a 4m by 4m room with 2.4m ceilings is about 38 square metres), take off roughly 1.7 square metres for a door and 1.2 for a window, and that room wants about 7 litres - two 5 litre tins, or a 10 to leave some for touching up. Ceilings and a second colour are extra, and a dark colour over a light wall often takes three coats.");
frame.store("PAINT_WITH_NO_SIZE", __v_322.clone())?;
frame.store("_paint_for_the_room", { let __signature_324 = Signature { name: "_paint_for_the_room".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_326 = Value::dict(); __attrs_326.dict_set(Value::from("__doc__"), Value::from("The litres for the wall or room in the line, or the method when the line has no size.\n\n    The size the person gave is the answer's raw material: a wall 6 metres long and 2.5 high is\n    15 square metres, and 15 square metres at two coats and 10 to 12 to the litre is about 3\n    litres. Handing back a worked example of a different room answers the method, not the\n    question. A room said as two sides is painted round its walls, so the perimeter times the\n    ceiling height is the area - the height the line names, or 2.4m. A line with no size in it\n    keeps the method, which is the only thing that can be said without one.\n    "))?; __attrs_326.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_327 = Value::dict(); __attrs_326.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_323 = Frame::module(frame.globals.clone()); let mut __function_325 = NativeFunction::qualified_with_origin("_paint_for_the_room".into(), "_paint_for_the_room".into(), "bot.knowledge.home_craft".into(), __attrs_326, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/home_craft.py", first: 646, last: 688, qualname: "_paint_for_the_room" }, closure: __closure_323.clone(), freevars: vec![] }, move |rt, args| __py_26::_paint_for_the_room(rt, __closure_323.clone(), &__signature_324, args)); __function_325 })?;
let __v_328 = Value::from("Count drops, not floor: divide the room's perimeter by the 52cm width of a standard roll and round up (a 4m by 4m room is 16m round, so 31 drops), then divide a roll's 10m by the ceiling height plus the pattern repeat to see how many drops each gives - usually three - and 31 drops is about 11 rolls. Buy one extra for a mistake and matching, and keep the batch number the same on every roll.");
frame.store("WALLPAPER_WITH_NO_SIZE", __v_328.clone())?;
frame.store("_wallpaper_for_the_room", { let __signature_330 = Signature { name: "_wallpaper_for_the_room".into(), positional: vec!["memory".into(),"understood".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_332 = Value::dict(); __attrs_332.dict_set(Value::from("__doc__"), Value::from("The rolls for the room in the line, or the method when the line has no size.\n\n    A room said as two sides is papered round its walls, so the wall area already worked out for\n    paint is the starting point: the perimeter is that area divided by the ceiling height, a\n    standard roll is 52cm wide, and a 10m roll gives four drops of a plain paper at a 2.4m ceiling\n    and three of a paper with a big repeat. A single wall has no perimeter to read the drops from,\n    so it keeps the method, which is also what a line with no size gets.\n    "))?; __attrs_332.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_333 = Value::dict(); __attrs_332.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_329 = Frame::module(frame.globals.clone()); let mut __function_331 = NativeFunction::qualified_with_origin("_wallpaper_for_the_room".into(), "_wallpaper_for_the_room".into(), "bot.knowledge.home_craft".into(), __attrs_332, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/home_craft.py", first: 699, last: 745, qualname: "_wallpaper_for_the_room" }, closure: __closure_329.clone(), freevars: vec![] }, move |rt, args| __py_27::_wallpaper_for_the_room(rt, __closure_329.clone(), &__signature_330, args)); __function_331 })?;
